// A table a reader reshapes in place: every transformation stays on a rail as a unit — not a command whose result is all
// that is left — so the shape on screen can be explained, undone and extended. The rail is `createModifiers`'s: a toolbar
// of buttons, and the panel under it is the unit's own settings (the columns it spans, the column it takes as input, its
// place in the stack). The table reads what the stack owns: a tint, a bar, an order.
//
// The values never leave the cells. A cell that became a coloured bar is still the number as text, so a reader on a screen
// reader, or with the stylesheet off, gets the table it was before the rail touched it; the tint and the bar are decoration
// and say so (`aria-hidden`).
import {
  createModifiers,
  type Modifier,
  type ModifierAction,
  type ModifierEncoding,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createSignal, For, Show } from "solid-js";

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** What `render` gets: the props of the figure, `data-part` and the caller's class merged in. */
export type ModifiersPartProps = PartProps;

/** A column of the table: its key in a row's cells, its label, and whether it is a number. */
export interface ModifiersColumn {
  readonly key: string;
  readonly label: string;
  readonly numeric?: boolean | undefined;
}

/** A row: an id the primitive and the story can name it by, and its cells. */
export interface ModifiersRow {
  readonly id: string;
  readonly cells: Readonly<Record<string, string | number>>;
}

export interface ModifiersProps extends Renderable<ModifiersPartProps, void> {
  readonly rows: ReadonlyArray<ModifiersRow>;
  /** The columns, in reading order; the first non-numeric one is the row header. */
  readonly columns: ReadonlyArray<ModifiersColumn>;
  /** The table's caption, which also names it. */
  readonly caption: string;
  readonly class?: string;
}

/**
 * The vocabulary this starter offers: one action per category the paper names — style (`Color`, `Size`) and layout
 * (`Sort`). Computation (aggregation, binning) is the half of MuTable a table of eight rows does not need.
 */
export const MODIFIER_ACTIONS: ReadonlyArray<ModifierAction> = [
  { kind: "color", label: "Color", encodings: ["color"] },
  { kind: "size", label: "Size", encodings: ["size"] },
  { kind: "sort", label: "Sort", encodings: ["order"] },
];

const actionOf = (kind: string): ModifierAction | undefined =>
  MODIFIER_ACTIONS.find((action) => action.kind === kind);

const labelOfPart = (part: { readonly kind: string }): string =>
  actionOf(part.kind)?.label ?? part.kind;

const figure = css.cn(css.display("grid"), css.gap(t.space._3), css.width("100%"), css.margin(0));

// The tools sit above the table they change: the add buttons, then the rail itself.
const tools = css.cn(
  css.display("flex"),
  css.gap(t.space._3),
  css.flexWrap("wrap"),
  css.alignItems("flex-start"),
);
const adds = css.cn(css.display("flex"), css.gap(t.space._2), css.flexWrap("wrap"));

// One button shape for the add buttons, the units and the panel's actions, since they are the same kind of control.
const control = css.cn(
  css.padding("2px 8px"),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.sm),
  css.bg(t.color.surface),
  css.color(t.color.text),
  css.fontSize(t.font.sizeSm),
  css.cursor("pointer"),
  css.disabled(css.opacity(0.45), css.cursor("not-allowed")),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("1px")),
);

const add = css.cn(control);

// The rail: the stack, in order, above the table. Empty is a state worth saying, not a hole to leave.
const rail = css.cn(
  css.display("flex"),
  css.gap(t.space._2),
  css.flexWrap("wrap"),
  css.alignItems("center"),
  css.minHeight(t.space._8),
  css.padding(t.space._1),
  css.border("1px dashed", t.color.border),
  css.borderRadius(t.radius.md),
);
const empty = css.cn(css.margin(0), css.fontSize(t.font.sizeSm), css.color(t.color.muted));
const unit = css.cn(
  control,
  css.attr("aria-expanded", "true")(css.bg(t.color.highlight), css.color(t.color.onHighlight)),
);
const unitCount = css.cn(css.marginInlineStart(t.space._1), css.opacity(0.7));

// The panel is the unit's own settings: a disclosure's region, opened by the unit above it.
const panel = css.cn(
  css.display("grid"),
  css.gap(t.space._2),
  css.padding(t.space._3),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.md),
  css.bg(t.color.surface),
  css.fontSize(t.font.sizeSm),
);
const panelTitle = css.cn(css.margin(0), css.fontWeight("600"));
const group = css.cn(
  css.display("flex"),
  css.gap(t.space._3),
  css.flexWrap("wrap"),
  css.margin(0),
  css.padding(0),
  css.border("none"),
);
const legend = css.cn(css.padding(0), css.fontSize(t.font.sizeSm), css.color(t.color.muted));
const choice = css.cn(
  css.display("inline-flex"),
  css.gap(t.space._1),
  css.alignItems("center"),
  css.cursor("pointer"),
);
const panelActions = css.cn(css.display("flex"), css.gap(t.space._2), css.flexWrap("wrap"));

const table = css.cn(
  css.width("100%"),
  css.borderCollapse("collapse"),
  css.fontSize(t.font.size),
  css.color(t.color.text),
);
const caption = css.cn(
  css.textAlign("start"),
  css.paddingBlock(t.space._2),
  css.color(t.color.muted),
  css.fontSize(t.font.sizeSm),
);
const headCell = css.cn(
  css.padding("4px 6px"),
  css.fontSize(t.font.sizeSm),
  css.fontWeight("500"),
  css.color(t.color.muted),
  css.borderBlockEnd("1px solid", t.color.border),
);
const rowHead = css.cn(
  css.padding("4px 6px"),
  css.fontWeight("500"),
  css.textAlign("start"),
  css.whiteSpace("nowrap"),
);

// A cell is a value first. The tint and the bar are layers over it, and the cell keeps the text where it was.
const cell = css.cn(
  css.position("relative"),
  css.padding("4px 6px"),
  css.textAlign("end"),
  css.fontVariantNumeric("tabular-nums"),
  css.borderBlockEnd("1px solid", t.color.border),
);
// The tint is the value's share of the column's scale, at the strength the bars use for a number that runs over them (a
// fifth of the highlight, not a solid): the cell's text sits on this wash, so the wash may not become a background.
const tinted = css.cn(
  css.bg("color-mix(in oklab, var(--color-highlight) calc(var(--share) * 22%), transparent)"),
);
// The bar is a rule under the number: a size encoding over a value that stays readable.
const bar = css.cn(
  css.position("absolute"),
  css.insetBlockEnd("0"),
  css.insetInlineStart("0"),
  css.height("3px"),
  css.bg(t.color.highlight),
  css.borderRadius("2px"),
);
const status = css.cn(
  css.margin(0),
  css.minHeight("1.25em"),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
);

const numberCell = css.cn();

/**
 * A table under a rail of transformations: add `Color`, `Size` or `Sort`, drag the rail's units by their menu, span a
 * unit over more than one column, lock one column as the input, and join two units into a reusable sequence.
 *
 * The mechanic is `@cssints/headless`'s `createModifiers`; everything a reader can reach with a pointer is also a menu
 * item or a key there, and every change is announced in the status line under the table.
 */
export const Modifiers = (props: ModifiersProps): JSX.Element => {
  const panelId = "modifiers-panel";
  const numbers = props.columns.filter((column) => column.numeric === true);
  const [open, setOpen] = createSignal<string | undefined>(undefined);
  const modifiers = createModifiers({
    targets: numbers.map((column) => ({ key: column.key, label: column.label })),
    actions: MODIFIER_ACTIONS,
    onActivate: (id) => setOpen((current) => (current === id ? undefined : id)),
  });

  const labelOfKey = (key: string): string =>
    props.columns.find((column) => column.key === key)?.label ?? key;
  const numberOf = (row: ModifiersRow, key: string): number => {
    const value = row.cells[key];
    return typeof value === "number" ? value : Number(value ?? 0);
  };
  const rangeOf = (key: string): { readonly min: number; readonly max: number } => {
    const values = props.rows
      .map((row) => numberOf(row, key))
      .filter((value) => Number.isFinite(value));
    const min = Math.min(...values);
    const max = Math.max(...values);
    // a flat column has no range to divide by; every share is then the same, full bar
    return { min: min === max ? min - 1 : min, max };
  };
  const shareOf = (key: string, value: number): number => {
    const range = rangeOf(key);
    const span = range.max - range.min;
    return span <= 0 ? 1 : Math.min(1, Math.max(0, (value - range.min) / span));
  };

  // The order encoding is the topmost unit that owns it: the stack's last `Sort`, over the first column it covers.
  const sortKey = (): string | undefined => {
    const steps = modifiers.steps();
    for (let index = steps.length - 1; index >= 0; index -= 1) {
      const step = steps[index];
      if (step === undefined) {
        continue;
      }
      const action = actionOf(step.kind);
      if (action !== undefined && action.encodings.includes("order") && step.targets.length > 0) {
        return step.targets[0];
      }
    }
    return undefined;
  };

  const rows = (): ReadonlyArray<ModifiersRow> => {
    const key = sortKey();
    const list = props.rows.slice();
    if (key === undefined) {
      return list;
    }
    // descending: a first look at a column asks "who is biggest", and a second `Sort` on another column answers again
    return list.sort((a, b) => numberOf(b, key) - numberOf(a, key));
  };

  const owners = (key: string): ReadonlyMap<ModifierEncoding, Modifier> => modifiers.encoded(key);
  const active = (): Modifier | undefined =>
    modifiers.modifiers().find((candidate) => candidate.id === open());

  const own = {
    "data-part": "modifiers",
    get class() {
      return css.cn(figure, props.class);
    },
  } as unknown as PartProps;

  return renderPart(props, own, undefined, (part) => (
    <figure {...part}>
      <div data-part="modifiers-tools" class={tools}>
        <div data-part="modifiers-add" class={adds} role="group" aria-label="Add a transformation">
          <For each={MODIFIER_ACTIONS}>
            {(action) => {
              const first = numbers[0]?.key;
              return (
                <button
                  type="button"
                  class={add}
                  disabled={first === undefined}
                  onClick={() => {
                    if (first === undefined) {
                      return;
                    }
                    const id = modifiers.add(action.kind, [first]);
                    if (id !== undefined) {
                      setOpen(id);
                    }
                  }}
                >
                  {`+ ${action.label}`}
                </button>
              );
            }}
          </For>
        </div>
        <div {...modifiers.toolbarProps} data-part="modifiers-rail" class={rail}>
          <For each={modifiers.modifiers()}>
            {(entry) => (
              <button
                {...modifiers.itemProps(entry.id)}
                type="button"
                data-part="modifiers-unit"
                class={unit}
                aria-expanded={open() === entry.id ? "true" : "false"}
                aria-controls={open() === entry.id ? panelId : undefined}
              >
                {entry.parts.map(labelOfPart).join(" + ")}
                <span class={unitCount} aria-hidden="true">
                  {entry.targets.length}
                </span>
              </button>
            )}
          </For>
          <Show when={modifiers.modifiers().length === 0}>
            <p data-part="modifiers-empty" class={empty}>
              No transformations yet: the table is the data, as it came.
            </p>
          </Show>
        </div>
      </div>

      <Show when={active()}>
        {(entry) => {
          const id = (): string => entry().id;
          const index = (): number =>
            modifiers.modifiers().findIndex((candidate) => candidate.id === id());
          const locked = (): number | null => entry().locked ?? null;
          return (
            <div
              data-part="modifiers-panel"
              class={panel}
              id={panelId}
              role="group"
              aria-labelledby={`${panelId}-title`}
            >
              <p class={panelTitle} id={`${panelId}-title`}>
                {modifiers.nameOf(id())}
              </p>
              <fieldset class={group}>
                <legend class={legend}>Applies to</legend>
                <For each={modifiers.targets}>
                  {(target) => (
                    <label class={choice}>
                      <input
                        type="checkbox"
                        checked={entry().targets.includes(target.key)}
                        onChange={() => modifiers.toggleTarget(id(), target.key)}
                      />
                      {target.label}
                    </label>
                  )}
                </For>
              </fieldset>
              <fieldset class={group}>
                <legend class={legend}>Uses as input</legend>
                <label class={choice}>
                  <input
                    type="radio"
                    name={`${panelId}-lock`}
                    checked={locked() === null}
                    onChange={() => modifiers.lock(id(), null)}
                  />
                  None
                </label>
                <For each={entry().targets}>
                  {(key, slot) => (
                    <label class={choice}>
                      <input
                        type="radio"
                        name={`${panelId}-lock`}
                        checked={locked() === slot()}
                        onChange={() => modifiers.lock(id(), slot())}
                      />
                      {labelOfKey(key)}
                    </label>
                  )}
                </For>
              </fieldset>
              <div class={panelActions} role="group" aria-label="Change the stack">
                <button
                  type="button"
                  class={control}
                  disabled={index() === 0}
                  onClick={() => modifiers.joinWithAbove(id())}
                >
                  Join with above
                </button>
                <button
                  type="button"
                  class={control}
                  disabled={entry().parts.length < 2}
                  onClick={() => modifiers.split(id())}
                >
                  Split
                </button>
                <button
                  type="button"
                  class={control}
                  disabled={index() === 0}
                  onClick={() => modifiers.move(id(), -1)}
                >
                  Move up
                </button>
                <button
                  type="button"
                  class={control}
                  disabled={index() === modifiers.modifiers().length - 1}
                  onClick={() => modifiers.move(id(), 1)}
                >
                  Move down
                </button>
                <button
                  type="button"
                  class={control}
                  onClick={() => {
                    modifiers.remove(id());
                    setOpen(undefined);
                  }}
                >
                  Remove
                </button>
              </div>
            </div>
          );
        }}
      </Show>

      <table data-part="modifiers-table" class={table}>
        <caption class={caption}>{props.caption}</caption>
        <thead>
          <tr>
            {/* the corner is the grid's first cell, not a header: it names nothing */}
            <td aria-hidden="true" class={headCell} />
            <For each={numbers}>
              {(column) => (
                <th scope="col" class={css.cn(headCell, css.textAlign("end"))}>
                  {column.label}
                </th>
              )}
            </For>
          </tr>
        </thead>
        <tbody>
          <For each={rows()}>
            {(row) => (
              <tr data-part="modifiers-row" data-row={row.id}>
                <For each={props.columns.filter((column) => column.numeric !== true)}>
                  {(column) => (
                    <th scope="row" class={rowHead}>
                      {row.cells[column.key]}
                    </th>
                  )}
                </For>
                <For each={numbers}>
                  {(column) => {
                    const value = (): number => numberOf(row, column.key);
                    return (
                      <td
                        data-part="modifiers-cell"
                        class={owners(column.key).has("color") ? css.cn(cell, tinted) : cell}
                        style={{ "--share": shareOf(column.key, value()) } as never}
                      >
                        <span class={numberCell}>{row.cells[column.key]}</span>
                        <Show when={owners(column.key).has("size")}>
                          <span
                            data-part="modifiers-bar"
                            aria-hidden="true"
                            class={bar}
                            style={{ width: `${Math.round(shareOf(column.key, value()) * 100)}%` }}
                          />
                        </Show>
                      </td>
                    );
                  }}
                </For>
              </tr>
            )}
          </For>
        </tbody>
      </table>

      <p {...modifiers.status.statusProps} data-part="modifiers-status" class={status}>
        {modifiers.status.message() ?? ""}
      </p>
    </figure>
  ));
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

// The modifiers' conformance: the mechanic is `createModifiers`', so what is proved here is the skin's half — the rail is
// a toolbar of one tab stop, the panel is the unit's settings, and the table reads what the stack owns while the values
// stay in the cells. Plus the one thing a starter exists to show: the pointer's routes and the keyboard's are the same.
import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import { afterEach, describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import { Modifiers, type ModifiersColumn, type ModifiersRow } from "./modifiers.tsx";

const mount = (element: () => JSX.Element) => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(element, root);
  const instance = {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
  live.push(instance);
  return instance;
};

const live: Array<{ dispose: () => void }> = [];

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

/** Solid delivers a click through its delegated listener on a later turn. */
const settle = (): Promise<void> => Promise.resolve();

const COLUMNS: ReadonlyArray<ModifiersColumn> = [
  { key: "title", label: "Film" },
  { key: "score", label: "Score", numeric: true },
  { key: "gross", label: "Gross", numeric: true },
];

const ROWS: ReadonlyArray<ModifiersRow> = [
  { id: "a", cells: { title: "A", score: 1, gross: 10 } },
  { id: "b", cells: { title: "B", score: 3, gross: 30 } },
  { id: "c", cells: { title: "C", score: 2, gross: 20 } },
];

const mounted = (): { root: HTMLElement } =>
  mount(() => <Modifiers rows={ROWS} columns={COLUMNS} caption="Three films" />);

const button = (root: HTMLElement, text: string): HTMLButtonElement => {
  const found = [...root.querySelectorAll<HTMLButtonElement>("button")].find(
    (candidate) => candidate.textContent?.trim().startsWith(text) === true,
  );
  if (found === undefined) {
    throw new Error(`no button ${text}`);
  }
  return found;
};

const units = (root: HTMLElement): HTMLButtonElement[] => [
  ...root.querySelectorAll<HTMLButtonElement>('[data-part="modifiers-unit"]'),
];
const rail = (root: HTMLElement): HTMLElement =>
  root.querySelector<HTMLElement>('[data-part="modifiers-rail"]')!;
const panel = (root: HTMLElement): HTMLElement | null =>
  root.querySelector<HTMLElement>('[data-part="modifiers-panel"]');
const status = (root: HTMLElement): string =>
  root.querySelector('[data-part="modifiers-status"]')?.textContent?.trim() ?? "";
const rowIds = (root: HTMLElement): string[] =>
  [...root.querySelectorAll<HTMLElement>('[data-part="modifiers-row"]')].map(
    (row) => row.dataset["row"] ?? "",
  );
/** A resolved paint's alpha, whether the browser prints `rgba()` or `oklab(… / a)` — a mix of 0 % is still "none". */
const alphaOf = (paint: string): number => {
  const slash = /\/\s*([\d.]+)\s*\)/.exec(paint);
  if (slash?.[1] !== undefined) {
    return Number(slash[1]);
  }
  const parts = /rgba?\(([^)]+)\)/.exec(paint)?.[1]?.split(",") ?? [];
  return parts.length === 4 ? Number(parts[3]) : 1;
};

const cell = (root: HTMLElement, row: string, index: number): HTMLElement =>
  root
    .querySelector<HTMLElement>(`[data-row="${row}"]`)!
    .querySelectorAll<HTMLElement>('[data-part="modifiers-cell"]')[index]!;

describe("Modifiers", () => {
  it("is a table of values before anything is added, and the rail says it is empty", () => {
    const { root } = mounted();
    expect(root.querySelectorAll('th[scope="col"]')).toHaveLength(2);
    expect(root.querySelectorAll('th[scope="row"]')).toHaveLength(3);
    expect(root.querySelectorAll('[data-part="modifiers-cell"]')).toHaveLength(6);
    expect(root.querySelector("caption")?.textContent).toBe("Three films");
    // every number is the cell's own text: the rail only changes how it is drawn
    expect(
      [...root.querySelectorAll('[data-part="modifiers-cell"]')].map((entry) =>
        entry.textContent?.trim(),
      ),
    ).toEqual(["1", "10", "3", "30", "2", "20"]);
    expect(units(root)).toHaveLength(0);
    expect(root.querySelector('[data-part="modifiers-empty"]')?.textContent).toContain(
      "No transformations yet",
    );
    // the rail is one tab stop, and it is the toolbar the primitive named
    expect(rail(root).getAttribute("role")).toBe("toolbar");
    expect(rail(root).getAttribute("aria-label")).toBe("Table transformations");
  });

  it("tints the cells a Color spans, keeps their values, and announces it", async () => {
    const { root } = mounted();
    expect(alphaOf(getComputedStyle(cell(root, "b", 0)).backgroundColor)).toBe(0);

    await userEvent.click(button(root, "+ Color"));
    await settle();

    expect(units(root)).toHaveLength(1);
    expect(units(root)[0]?.getAttribute("aria-expanded")).toBe("true");
    expect(units(root)[0]?.getAttribute("aria-label")).toBe("Color, applied to Score");
    // the top of the scale is the strongest tint; the bottom is none, and both keep their number
    expect(alphaOf(getComputedStyle(cell(root, "b", 0)).backgroundColor)).toBeGreaterThan(0);
    expect(alphaOf(getComputedStyle(cell(root, "a", 0)).backgroundColor)).toBe(0);
    expect(cell(root, "b", 0).textContent?.trim()).toBe("3");
    expect(status(root)).toBe("Color added, applied to Score");
  });

  it("draws a Size as a bar over the value, and the bar is decoration", async () => {
    const { root } = mounted();
    await userEvent.click(button(root, "+ Size"));
    await settle();

    const bars = (): HTMLElement[] => [
      ...root.querySelectorAll<HTMLElement>('[data-part="modifiers-bar"]'),
    ];
    expect(bars()).toHaveLength(3);
    // the largest value has the full bar, the smallest none of it
    expect(bars()[1]?.style.width).toBe("100%");
    expect(bars()[0]?.style.width).toBe("0%");
    expect(bars()[1]?.getAttribute("aria-hidden")).toBe("true");
    expect(cell(root, "b", 0).textContent?.trim()).toBe("3");
  });

  it("reorders the rows for a Sort, and the values travel with their labels", async () => {
    const { root } = mounted();
    await userEvent.click(button(root, "+ Sort"));
    await settle();

    expect(rowIds(root)).toEqual(["b", "c", "a"]);
    expect(root.querySelector('[data-row="b"] th')?.textContent).toBe("B");
    expect(
      root.querySelector('[data-row="b"] [data-part="modifiers-cell"]')?.textContent?.trim(),
    ).toBe("3");
    expect(status(root)).toBe("Sort added, applied to Score");
  });

  it("opens the unit's settings: the span, the input column, and the stack's moves", async () => {
    const { root } = mounted();
    const open = (): HTMLElement => panel(root) as HTMLElement;

    await userEvent.click(button(root, "+ Color"));
    await settle();
    expect(open().textContent).toContain("Color, applied to Score");
    // one checkbox per column the vocabulary knows, one radio per column the unit spans
    expect(open().querySelectorAll('input[type="checkbox"]')).toHaveLength(2);
    expect(open().querySelectorAll('input[type="radio"]')).toHaveLength(2);

    const gross = [...open().querySelectorAll<HTMLInputElement>('input[type="checkbox"]')][1]!;
    await userEvent.click(gross);
    await settle();
    expect(units(root)[0]?.textContent).toContain("Color");
    expect(units(root)[0]?.getAttribute("aria-label")).toBe("Color, applied to Score, Gross");
    expect(status(root)).toBe("Color, applied to Score, Gross");

    const lock = [...open().querySelectorAll<HTMLInputElement>('input[type="radio"]')][1]!;
    await userEvent.click(lock);
    await settle();
    expect(status(root)).toBe("Color, locked to Score");
    expect(open().textContent).toContain("locked to Score");
  });

  it("joins two units into one sequence, splits it back, and moves it in the stack", async () => {
    const { root } = mounted();
    await userEvent.click(button(root, "+ Color"));
    await settle();
    await userEvent.click(button(root, "+ Size"));
    await settle();
    expect(units(root).map((entry) => entry.textContent?.trim())).toEqual(["Color1", "Size1"]);

    await userEvent.click(button(root, "Join with above"));
    await settle();
    expect(units(root)).toHaveLength(1);
    expect(units(root)[0]?.getAttribute("aria-label")).toBe("Color + Size, applied to Score");
    expect(status(root)).toBe("2 modifiers joined");

    await userEvent.click(button(root, "Split"));
    await settle();
    expect(units(root)).toHaveLength(2);
    expect(status(root)).toBe("joined unit split");

    // the split kept the joined id on its first piece, so the panel is still that unit's
    await userEvent.click(button(root, "Move down"));
    await settle();
    expect(units(root).map((entry) => entry.getAttribute("aria-label"))).toEqual([
      "Size, applied to Score",
      "Color, applied to Score",
    ]);
    expect(status(root)).toBe("Color moved to position 2 of 2");

    await userEvent.click(button(root, "Remove"));
    await settle();
    expect(units(root)).toHaveLength(1);
    expect(panel(root)).toBeNull();
  });

  it("is one tab stop, and Alt+Arrow reorders the stack from the keyboard", async () => {
    const { root } = mounted();
    await userEvent.click(button(root, "+ Color"));
    await settle();
    await userEvent.click(button(root, "+ Size"));
    await settle();

    const [first, second] = units(root);
    // the tab stop is the unit the reader last touched: the one just added
    expect(first?.tabIndex).toBe(-1);
    expect(second?.tabIndex).toBe(0);

    second?.focus();
    await userEvent.keyboard("{Alt>}{ArrowUp}{/Alt}");
    await settle();

    expect(units(root).map((entry) => entry.getAttribute("aria-label"))).toEqual([
      "Size, applied to Score",
      "Color, applied to Score",
    ]);
    expect(status(root)).toBe("Size moved to position 1 of 2");
    // the moved unit kept the focus, and the panel followed it
    expect(document.activeElement).toBe(units(root)[0]);
    expect(panel(root)?.textContent).toContain("Size, applied to Score");
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
